// Rust translation of linux/soc/mediatek/infracfg.h.
// BIT and GENMASK are kept as local equivalents of the kernel macros.
pub const fn bit(n: u32) -> u32 { 1u32 << n }
pub const fn genmask(hi: u32, lo: u32) -> u32 {
    if hi == 31 && lo == 0 { u32::MAX } else { (((1u64 << (hi - lo + 1)) - 1) << lo) as u32 }
}

